class RecoveryScheduler
{
public:
    void Tick(
        ProjectSession& session,
        TimePoint now)
    {
        if (
            !session.HasUnsavedChanges())
        {
            return;
        }

        if (
            now - m_LastSnapshot <
            m_Interval)
        {
            return;
        }

        session.CreateRecoveryPoint();

        m_LastSnapshot = now;
    }

private:
    Duration m_Interval =
        std::chrono::minutes(2);

    TimePoint m_LastSnapshot{};
};

